:root {
  /* Colors */
  --color-paper-canvas: #ffffff;
  --color-linen-wash: #f9f9f8;
  --color-ink: #000000;
  --color-jet-display: #000000f2;
  --color-carbon-body: #000000e5;
  --color-charcoal-mark: #000000bf;
  --color-pebble-stat: #615d59;
  --color-graphite-caption: #0000008a;
  --color-ash-border: #0000001a;
  --color-lapis-signal: #0075de;
  --color-lapis-ink: #005bab;
  --color-lapis-mist: #e6f3fe;
  --color-apricot-highlight: #ffdec4;

  /* Typography — Font Families */
  --font-notioninter: "NotionInter", "Inter", ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
  --font-lyon-text: "Lyon Text", "Source Serif 4", ui-serif, Georgia, Cambria, "Times New Roman", Times, serif;

  /* Typography — Scale */
  --text-small: 12px;
  --leading-small: 1.33;
  --tracking-small: 0.125px;
  --text-caption: 14px;
  --leading-caption: 1.43;
  --tracking-caption: 0px;
  --text-body-sm: 14px;
  --leading-body-sm: 1.43;
  --tracking-body-sm: 0px;
  --text-body: 16px;
  --leading-body: 1.5;
  --tracking-body: 0px;
  --text-body-lg: 20px;
  --leading-body-lg: 1.4;
  --tracking-body-lg: -0.125px;
  --text-subheading: 20px;
  --leading-subheading: 1.4;
  --tracking-subheading: -0.125px;
  --text-heading-sm: 22px;
  --leading-heading-sm: 1.27;
  --tracking-heading-sm: -0.25px;
  --text-heading: 42px;
  --leading-heading: 1.14;
  --tracking-heading: -1.5px;
  --text-heading-lg: 54px;
  --leading-heading-lg: 1.04;
  --tracking-heading-lg: -1.875px;
  --text-display: 96px;
  --leading-display: 1.04;
  --tracking-display: -4.6px;

  /* Typography — Weights */
  --font-weight-regular: 400;
  --font-weight-medium: 500;
  --font-weight-semibold: 600;
  --font-weight-bold: 700;

  /* Spacing */
  --spacing-4: 4px;
  --spacing-5: 5px;
  --spacing-6: 6px;
  --spacing-8: 8px;
  --spacing-10: 10px;
  --spacing-12: 12px;
  --spacing-14: 14px;
  --spacing-15: 15px;
  --spacing-16: 16px;
  --spacing-24: 24px;
  --spacing-28: 28px;
  --spacing-32: 32px;
  --spacing-40: 40px;
  --spacing-64: 64px;
  --spacing-80: 80px;
  --spacing-96: 96px;

  /* Layout */
  --layout-max-width: 1252px;
  --layout-section-gap: 96px;
  --layout-card-padding: 24px;
  --layout-element-gap: 8px;

  /* Border Radius */
  --radius-sm: 4px;
  --radius-md: 8px;
  --radius-lg: 12px;
  --radius-full: 9999px;

  /* Named Radii */
  --radius-cards: 12px;
  --radius-buttons: 8px;
  --radius-nav: 4px;
  --radius-small-elements: 4px;
  --radius-images: 12px;
  --radius-pills: 9999px;
  --radius-tags: 9999px;
  --radius-avatars: 50%;

  /* Shadows */
  --shadow-sm: rgba(0,0,0,0.01) 0px 0.175px 1.041px 0px, rgba(0,0,0,0.02) 0px 0.8px 2.925px 0px, rgba(0,0,0,0.027) 0px 2.025px 7.847px 0px, rgba(0,0,0,0.04) 0px 4px 18px 0px;
  --shadow-lg: rgba(0,0,0,0.008) 0px 0.667px 3.502px 0px, rgba(0,0,0,0.016) 0px 2.933px 7.252px 0px, rgba(0,0,0,0.02) 0px 7.2px 14.462px 0px, rgba(0,0,0,0.024) 0px 13.867px 28.348px 0px, rgba(0,0,0,0.03) 0px 23.333px 52.123px 0px, rgba(0,0,0,0.04) 0px 36px 89px 0px;

  /* Surfaces */
  --surface-paper-canvas: #ffffff;
  --surface-linen-wash: #f9f9f8;
  --surface-lapis-mist: #e6f3fe;
  --surface-ink: #000000;
}

